function setRetryCount(count) {
  // BUG with || when 0 is valid:
  const retries = count || 3;  // 0 becomes 3

  // Fix with ?? — only null/undefined trigger default:
  const safe = count ?? 3;     // 0 stays 0
  return safe;
}

console.log(setRetryCount(0));       // was 3, now 0
console.log(setRetryCount(null));    // 3
console.log(setRetryCount(undefined)); // 3

const title = '';
console.log(title || 'Untitled');  // 'Untitled' — empty string is falsy
console.log(title ?? 'Untitled');  // '' — empty string is not nullish

function processConfig(config) {
  // Existence guard — null or undefined:
  if (config == null) {
    throw new Error('config required');
  }

  // Boolean flag — do not rely on truthiness for false:
  const debug = config.debug === true;

  // Optional string with fallback for empty:
  const name = config.name?.trim() || 'Anonymous';

  // Numeric with nullish default only:
  const timeout = config.timeout ?? 5000;

  return { debug, name, timeout };
}
